const grid = $input.first().json.data;
let accessibleRollCount = 0;

/**
 * Get a specific position in the grid. If walking outside the grid, we simply return 
 * `.` to indicate an empty position, as that will stop the logic.
 */
const getItemAtPosition = (x, y) => {
  if (y < 0 || y >= grid.length) return "."
  if (x < 0 || x >= grid[y].length) return "."
  return grid[y][x]
};

const checkPosition = (x, y) => {
  if (getItemAtPosition(x, y) != '@') return;

  let neighbourCount = 0;
  // Count neighbours by loo
  for (let distanceY = -1; distanceY <= 1; distanceY++) {
    for (let distanceX = -1; distanceX <= 1; distanceX++) {
      if (getItemAtPosition(x + distanceX, y + distanceY) === '@') neighbourCount++;
    }
  }

  if (neighbourCount <= 4) {
    accessibleRollCount++;
  }
};

for (let y = 0; y < grid.length; y++) {
  for (let x = 0; x < grid[y].length; x++) {
    checkPosition(x, y);
  }
}

return { accessibleRollCount, data: grid }

